from collections import Counter

def histogram(test):
    """Given a string representing space-separated lowercase letters, return a dictionary
    of the letter(s) with the highest repetition and their corresponding count.
    If several letters have the same occurrence, return all of them.
    """
    if not test or not test.strip():
        return {}
    tokens = [t for t in test.split(' ') if t]  # ignore empty tokens from multiple spaces
    if not tokens:
        return {}
    counts = Counter(tokens)
    if not counts:
        return {}
    max_count = max(counts.values())
    return {k: v for k, v in counts.items() if v == max_count}
